function parseCsv(text){
  var lines=String(text||'').split(/\r?\n/).filter(function(l){return l.trim();});
  if(lines.length<2) return { rows:null, error:'\u81f3\u5c11\u9700\u8981\u8868\u5934 + 1 \u884c\u6570\u636e' };
  var head=lines[0].split(',').map(function(h){return h.trim();});
  var rows=[];
  for(var i=1;i<lines.length;i++){
    var cells=lines[i].split(',').map(function(c){return c.trim();});
    if(cells.length!==head.length) return { rows:null, error:'\u7b2c '+(i+1)+' \u884c\u5217\u6570\u4e0d\u5339\u914d' };
    var o={};
    for(var j=0;j<head.length;j++) o[head[j]]=cells[j];
    rows.push(o);
  }
  return { rows:rows, error:null };
}
function aggregate(values, agg){
  if(!values.length) return null;
  if(agg==='count') return values.length;
  var nums=values.map(Number);
  if(agg==='sum') return nums.reduce(function(a,b){return a+b;},0);
  if(agg==='avg') return nums.reduce(function(a,b){return a+b;},0)/nums.length;
  if(agg==='min') return Math.min.apply(null,nums);
  if(agg==='max') return Math.max.apply(null,nums);
  throw new Error('UNKNOWN_AGG');
}
function pivot(rows, rowKey, colKey, valKey, agg){
  agg=agg||'sum';
  var rset={}, cset={}, cells={};
  rows.forEach(function(r){
    if(!(rowKey in r)||!(colKey in r)) throw new Error('KEY_NOT_FOUND');
    var rk=r[rowKey], ck=r[colKey];
    rset[rk]=1; cset[ck]=1;
    var key=rk+'\u0000'+ck;
    (cells[key]=cells[key]||[]).push(r[valKey]);
  });
  var rkeys=Object.keys(rset).sort(), ckeys=Object.keys(cset).sort();
  var matrix=rkeys.map(function(rk){
    return ckeys.map(function(ck){
      var v=cells[rk+'\u0000'+ck];
      return v ? aggregate(v, agg) : null;
    });
  });
  var rowTotals=matrix.map(function(row){
    var vs=row.filter(function(v){return v!==null;});
    return vs.length ? (agg==='count'?vs.reduce(function(a,b){return a+b;},0):aggregate(vs,agg==='avg'?'avg':agg)) : null;
  });
  var colTotals=ckeys.map(function(_,j){
    var vs=matrix.map(function(row){return row[j];}).filter(function(v){return v!==null;});
    return vs.length ? (agg==='count'?vs.reduce(function(a,b){return a+b;},0):aggregate(vs,agg==='avg'?'avg':agg)) : null;
  });
  var all=[];
  matrix.forEach(function(row){ row.forEach(function(v){ if(v!==null) all.push(v); }); });
  var grand=all.length ? (agg==='count'?all.reduce(function(a,b){return a+b;},0):aggregate(all,agg==='avg'?'avg':agg)) : null;
  return { rows:rkeys, cols:ckeys, matrix:matrix, rowTotals:rowTotals, colTotals:colTotals, grand:grand };
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { parseCsv:parseCsv, aggregate:aggregate, pivot:pivot };
}
if (typeof window !== 'undefined') {
  window.PivotForgePure = { parseCsv:parseCsv, aggregate:aggregate, pivot:pivot };
}
